patch:
diff --git a/repro/win32-cross-drive.js b/repro/win32-cross-drive.js
new file mode 100644
index 0000000..ae78a28
--- /dev/null
+++ b/repro/win32-cross-drive.js
@@ -0,0 +1,86 @@
+"use strict";
+
+/*
+ * Reproduction for "files on a different drive are not ignored on Windows".
+ * This machine is not Windows, so Windows path semantics are emulated by
+ * replacing the methods of the shared `node:path` module with `path.win32`
+ * before ESLint (and @eslint/config-array) are loaded, and by faking the cwd.
+ */
+
+const Module = require("node:module");
+const path = require("node:path");
+const win32 = path.win32;
+const posix = { ...path };
+
+/** Copies the path API of `impl` onto the shared `node:path` object. */
+function usePathImpl(impl) {
+    for (const key of Object.keys(win32)) {
+        if (key !== "win32" && key !== "posix") {
+            path[key] = impl[key];
+        }
+    }
+}
+
+// Node's module loader shares this object, so resolve modules with POSIX semantics.
+// Module loading (and module top-level code) runs with POSIX semantics.
+const originalRequire = Module.prototype.require;
+let requireDepth = 0;
+
+Module.prototype.require = function(...args) {
+    if (requireDepth++ === 0) {
+        usePathImpl(posix);
+    }
+    try {
+        return originalRequire.apply(this, args);
+    } finally {
+        if (--requireDepth === 0) {
+            usePathImpl(win32);
+        }
+    }
+};
+
+const apiPath = path.join(__dirname, "../lib/api");
+
+usePathImpl(win32);
+
+const CWD = "C:\\Project";
+
+process.cwd = () => CWD;
+
+const { Linter, ESLint } = require(apiPath);
+
+const cases = [
+    ["inside cwd           ", "C:\\Project\\foo.js"],
+    ["same drive, outside  ", "C:\\other\\foo.js"],
+    ["different drive (bug)", "F:\\foo.js"]
+];
+
+(async () => {
+    console.log(`path.relative(${JSON.stringify(CWD)}, "F:\\\\foo.js") = ${JSON.stringify(path.relative(CWD, "F:\\foo.js"))}\n`);
+
+    console.log("== Linter#verify (configType: flat, cwd: C:\\Project) ==");
+    const linter = new Linter({ configType: "flat" });
+
+    for (const [label, file] of cases) {
+        const msgs = linter.verify("foo()", { rules: { "no-undef": "error" } }, file);
+
+        console.log(`${label} ${file.padEnd(20)} -> ${msgs.map(m => `${m.ruleId ?? "(no rule)"}: ${m.message}`).join(" | ") || "(no messages)"}`);
+    }
+
+    console.log("\n== ESLint#lintText (overrideConfigFile: true, cwd: C:\\Project, warnIgnored: true) ==");
+    const eslint = new ESLint({
+        cwd: CWD,
+        overrideConfigFile: true,
+        overrideConfig: { rules: { "no-undef": "error" } }
+    });
+
+    for (const [label, file] of cases) {
+        const [result] = await eslint.lintText("foo();\n", { filePath: file, warnIgnored: true });
+        const ignored = await eslint.isPathIgnored(file);
+
+        console.log(`${label} ${file.padEnd(20)} isPathIgnored=${ignored} -> ${result.messages.map(m => `${m.ruleId ?? "(no rule)"}: ${m.message}`).join(" | ")}`);
+    }
+})().catch(err => {
+    console.error(err);
+    process.exitCode = 1;
+});
